#!/usr/bin/env node
/**
 * Randomized differential corpus generator.
 *
 * Emits a JSON array of argv arrays on stdout. Every case is a well-formed
 * `--payload X --secret Y` invocation; the interesting variation lives in the
 * two operand strings, not in the argparse surface (that is covered by the
 * hand-written corpus in tools/gencases.mjs).
 *
 *   node gen.mjs <pairsWanted> <seed>
 *
 * Constraints imposed by the transport rather than by the program under test:
 *   - a NUL byte cannot survive execve(), so U+0000 is never generated;
 *   - lone surrogates are rewritten to U+FFFD by the kernel-facing encoder, so
 *     generating them would only test U+FFFD twice. Excluded.
 *   - Linux caps a single argv entry at MAX_ARG_STRLEN (128 KiB). Long-string
 *     cases are budgeted in *bytes* to stay clear of that ceiling.
 */

// ------------------------------------------------------------------ prng
/** xorshift128+, seeded, so a failing corpus can be regenerated exactly. */
function makeRng(seed) {
  let s0 = seed >>> 0 || 1;
  let s1 = (seed * 2654435761) >>> 0 || 2;
  let s2 = 0x9e3779b9;
  let s3 = 0x85ebca6b;
  return function next() {
    let t = s3;
    const s = s0;
    s3 = s2;
    s2 = s1;
    s1 = s;
    t ^= t << 11;
    t ^= t >>> 8;
    s0 = (t ^ s ^ (s >>> 19)) >>> 0;
    return s0 / 4294967296;
  };
}

const SEED = Number(process.argv[3] ?? 20260809);
const rnd = makeRng(SEED);

const int = (n) => Math.floor(rnd() * n);
const between = (lo, hi) => lo + int(hi - lo + 1);
const pick = (arr) => arr[int(arr.length)];
const cp = (...pts) => pts.map((p) => String.fromCodePoint(p)).join('');

// ------------------------------------------------------- character palettes

/** Printable ASCII, punctuation included, plus the two whitespace bytes that
 *  can legally travel through argv. */
const ASCII_PRINTABLE = [];
for (let c = 0x20; c <= 0x7e; c++) ASCII_PRINTABLE.push(String.fromCharCode(c));
const ASCII_WS = ['\t', '\n', '\r'];

/** Characters that either JSON or CPython's repr has to escape, plus the ones
 *  that sit right on the printability boundary Python uses to decide. */
const ESCAPEY = [
  '"', "'", '\\', '/', '\b', '\f', '\n', '\r', '\t', '\v', '\x07', '\x1b', '\x00'.replace('\x00', '\x01'),
  cp(0x02), cp(0x1f), cp(0x7f), cp(0x80), cp(0x85), cp(0x9f),
  cp(0xa0), cp(0xad), cp(0x61c), cp(0x1680), cp(0x180e), cp(0x2000), cp(0x2007), cp(0x200b),
  cp(0x200c), cp(0x200d), cp(0x200e), cp(0x200f), cp(0x2028), cp(0x2029), cp(0x202a), cp(0x202e),
  cp(0x2060), cp(0x2066), cp(0x2069), cp(0x205f), cp(0x3000), cp(0xfeff), cp(0xfff9), cp(0xfffb),
  cp(0xfffe), cp(0xffff), cp(0xe000), cp(0xf8ff), cp(0xfffd), cp(0xd7ff),
  cp(0x378), cp(0x5ff), cp(0x1c90), cp(0xe0001), cp(0xe0020), cp(0xe0100),
  cp(0xf0000), cp(0x10fffe), cp(0x10ffff),
  cp(0x1d11e), cp(0x1f600), cp(0x2070e),
  'a', 'Z', '0', ' ',
];

const JSONISH = [
  '{"a":1}', '{"data":"x"}', '[]', '{}', 'null', 'true', 'false', '0', '-0', '1e309', 'NaN',
  'Infinity', '-Infinity', '{"a":', '"', '""', '\\"', '{"a":"\\u0000"}', '{"a":"\\ud83d\\ude00"}',
  'a.b.c', 'a.b', '.', '..', '...', '==', '=', '-_', '-', '_', '+/', 'eyJhbGciOiJIUzI1NiJ9',
  'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJkYXRhIjoieCJ9.sig',
  'Bearer x.y.z', '%7B%22a%22%3A1%7D', '\\u0041', '\\\\', '\\n', '\\t',
  'YWJj', 'YWJjZA==', 'YWJjZGU=', '?', '#', '&', '%', '$', '@', '!',
];

// ------------------------------------------------------------- generators

/** 1. Random ASCII including all printable punctuation (and tab/newline/CR). */
function genAscii() {
  const n = between(0, 120);
  let s = '';
  for (let i = 0; i < n; i++) s += rnd() < 0.06 ? pick(ASCII_WS) : pick(ASCII_PRINTABLE);
  return s;
}

/** 2. Random bytes decoded as UTF-8 -- i.e. uniformly random *valid* UTF-8
 *     sequences, weighted by encoded length so all four forms appear. */
function genUtf8Bytes() {
  const n = between(0, 60);
  let s = '';
  for (let i = 0; i < n; i++) {
    const width = pick([1, 1, 2, 2, 3, 3, 4]);
    let c;
    if (width === 1) c = between(0x01, 0x7f);
    else if (width === 2) c = between(0x80, 0x7ff);
    else if (width === 3) {
      do {
        c = between(0x800, 0xffff);
      } while (c >= 0xd800 && c <= 0xdfff);
    } else c = between(0x10000, 0x10ffff);
    s += String.fromCodePoint(c);
  }
  return s;
}

/** 3. Full Unicode range, astral characters included, uniform over scalars. */
function genUnicode() {
  const n = between(0, 60);
  let s = '';
  for (let i = 0; i < n; i++) {
    let c;
    do {
      c = between(0x01, 0x10ffff);
    } while (c >= 0xd800 && c <= 0xdfff);
    s += String.fromCodePoint(c);
  }
  return s;
}

/** 4. Built purely from characters JSON or repr must escape. */
function genEscapey() {
  const n = between(1, 40);
  let s = '';
  for (let i = 0; i < n; i++) s += pick(ESCAPEY);
  return s;
}

/** 5. Very long strings, 1 KiB - 64 KiB, budgeted in UTF-8 bytes. */
function genLong() {
  const targetBytes = between(1024, 65536);
  const mode = int(4);
  let s = '';
  if (mode === 0) {
    s = pick(ASCII_PRINTABLE).repeat(targetBytes);
  } else if (mode === 1) {
    while (Buffer.byteLength(s, 'utf8') < targetBytes) s += genAscii() + pick(ASCII_PRINTABLE);
  } else if (mode === 2) {
    const unit = pick(['é', '你', '😀', cp(0x2028), '\\', '"', "'", '\t\n']);
    s = unit.repeat(Math.max(1, Math.ceil(targetBytes / Buffer.byteLength(unit, 'utf8'))));
  } else {
    while (Buffer.byteLength(s, 'utf8') < targetBytes) s += genEscapey();
  }
  // Trim back to the byte budget without splitting a code point.
  while (Buffer.byteLength(s, 'utf8') > targetBytes) s = s.slice(0, -1);
  return s;
}

/** 6. Pure whitespace, pure quotes, or pure backslashes. */
function genHomogeneous() {
  const unit = pick([
    ' ', '\t', '\n', '\r', '\r\n', ' \t\n', cp(0xa0), cp(0x2000), cp(0x3000), cp(0x2028), cp(0x2029),
    '"', "'", '"\'', '\\', '\\\\', '\\"', "\\'", '`',
  ]);
  return unit.repeat(between(1, 64));
}

/** 7. Fragments that look like JSON or JWT. */
function genJsonish() {
  if (rnd() < 0.4) return pick(JSONISH);
  const n = between(1, 8);
  let s = '';
  for (let i = 0; i < n; i++) s += pick(JSONISH);
  return s;
}

/** 8. Concatenation across the other generators, to catch interactions
 *     (e.g. a control character adjacent to a multi-byte sequence at a
 *     SHA-256 block boundary). */
const BASE = [genAscii, genUtf8Bytes, genUnicode, genEscapey, genHomogeneous, genJsonish];
function genMixed() {
  const n = between(2, 5);
  let s = '';
  for (let i = 0; i < n; i++) s += pick(BASE)();
  // Nudge toward SHA-256 block boundaries: 55/56/63/64/119/120 byte lengths.
  const target = pick([31, 32, 33, 54, 55, 56, 57, 63, 64, 65, 111, 112, 119, 120, 127, 128, 129]);
  while (Buffer.byteLength(s, 'utf8') > target) s = s.slice(0, -1);
  if (rnd() < 0.5) while (Buffer.byteLength(s, 'utf8') < target) s += pick(ASCII_PRINTABLE);
  return s;
}

const GENERATORS = [
  genAscii, genUtf8Bytes, genUnicode, genEscapey, genLong, genHomogeneous, genJsonish, genMixed,
];

// ------------------------------------------------------------------- emit

const WANT = Number(process.argv[2] ?? 4000);
const MAX_ARG_BYTES = 100 * 1024; // comfortably under Linux MAX_ARG_STRLEN (128 KiB)

/** @type {string[][]} */
const cases = [];
let i = 0;
while (cases.length < WANT) {
  // Round-robin the generator for payload so the mix stays even, and choose the
  // secret's generator independently so cross-category pairs occur too.
  const payload = GENERATORS[i % GENERATORS.length]();
  const secret = rnd() < 0.5 ? GENERATORS[i % GENERATORS.length]() : pick(GENERATORS)();
  i++;
  if (Buffer.byteLength(payload, 'utf8') > MAX_ARG_BYTES) continue;
  if (Buffer.byteLength(secret, 'utf8') > MAX_ARG_BYTES) continue;
  if (payload.includes('\0') || secret.includes('\0')) continue;
  cases.push(['--payload', payload, '--secret', secret]);
}

process.stdout.write(JSON.stringify(cases));

#!/usr/bin/env node
/**
 * Parallel differential runner.
 *
 *   node run.mjs cases.json [concurrency]
 *
 * Spawns the reference build and the port over identical argv and compares
 * stdout bytes, stderr bytes and exit status. Mismatches are written to
 * mismatches.json next to the corpus, with argv preserved exactly so any
 * failure can be replayed by hand.
 */

import { spawn } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { cpus } from 'node:os';

const REFERENCE = '/workspace/dataset/test8_executable';
const PORT = '/output/test8.mjs';

/** @returns {Promise<{out: Buffer, err: Buffer, code: number|null, signal: string|null}>} */
function run(cmd, argv) {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, argv, { stdio: ['ignore', 'pipe', 'pipe'] });
    /** @type {Buffer[]} */ const out = [];
    /** @type {Buffer[]} */ const err = [];
    child.stdout.on('data', (d) => out.push(d));
    child.stderr.on('data', (d) => err.push(d));
    child.on('error', reject);
    child.on('close', (code, signal) =>
      resolve({ out: Buffer.concat(out), err: Buffer.concat(err), code, signal }),
    );
  });
}

const casesPath = process.argv[2];
const CONC = Number(process.argv[3] ?? Math.min(24, cpus().length));
/** @type {string[][]} */
const cases = JSON.parse(readFileSync(casesPath, 'utf8'));

const mismatches = [];
let executed = 0;
let cursor = 0;

const clip = (buf) => {
  const s = buf.toString('utf8');
  return s.length > 1500 ? s.slice(0, 1500) + `…[+${s.length - 1500} chars]` : s;
};

async function worker() {
  for (;;) {
    const idx = cursor++;
    if (idx >= cases.length) return;
    const argv = cases[idx];
    const [a, b] = await Promise.all([run(REFERENCE, argv), run(process.execPath, [PORT, ...argv])]);
    executed++;

    const sameOut = Buffer.compare(a.out, b.out) === 0;
    const sameErr = Buffer.compare(a.err, b.err) === 0;
    const sameCode = a.code === b.code && a.signal === b.signal;
    if (sameOut && sameErr && sameCode) continue;

    const detail = [];
    if (!sameCode) detail.push(`exit: reference=${a.code}/${a.signal} port=${b.code}/${b.signal}`);
    if (!sameOut) {
      let i = 0;
      while (i < a.out.length && i < b.out.length && a.out[i] === b.out[i]) i++;
      detail.push(
        `stdout differs at byte ${i} (reference ${a.out.length} bytes, port ${b.out.length} bytes)`,
      );
    }
    if (!sameErr) detail.push('stderr differs');

    mismatches.push({
      argvJson: JSON.stringify(argv),
      referenceOutput: clip(Buffer.concat([a.out, a.err])),
      portOutput: clip(Buffer.concat([b.out, b.err])),
      detail: detail.join('; '),
    });
    process.stderr.write(`MISMATCH #${idx}: ${detail.join('; ')}\n`);
  }
}

const t0 = Date.now();
const ticker = setInterval(() => {
  process.stderr.write(`  ${executed}/${cases.length} run, ${mismatches.length} mismatched\n`);
}, 15000);

await Promise.all(Array.from({ length: CONC }, worker));
clearInterval(ticker);

writeFileSync(casesPath.replace(/\.json$/, '') + '.mismatches.json', JSON.stringify(mismatches, null, 2));
process.stderr.write(
  `\ndone: ${executed} pairs in ${((Date.now() - t0) / 1000).toFixed(1)}s, ${mismatches.length} mismatches\n`,
);
