import { readFileSync } from 'node:fs';
const a = JSON.parse(readFileSync('/tmp/fuzz/cases.json', 'utf8'));
console.log('cases:', a.length);
let maxB = 0, tot = 0;
for (const x of a) for (const s of [x[1], x[3]]) { const b = Buffer.byteLength(s, 'utf8'); if (b > maxB) maxB = b; tot += b; }
console.log('max arg bytes:', maxB, 'corpus bytes:', tot);
const NUL = String.fromCharCode(0);
console.log('nul present:', a.some((x) => x[1].includes(NUL) || x[3].includes(NUL)));
const lone = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/;
console.log('lone surrogate present:', a.some((x) => lone.test(x[1]) || lone.test(x[3])));
let astral = 0, ctrl = 0, longs = 0;
for (const x of a) {
  const s = x[1] + x[3];
  if (/[\u{10000}-\u{10FFFF}]/u.test(s)) astral++;
  if (/[\x01-\x1F\x7F]/.test(s)) ctrl++;
  if (Buffer.byteLength(x[1], 'utf8') >= 1024 || Buffer.byteLength(x[3], 'utf8') >= 1024) longs++;
}
console.log('with astral:', astral, 'with controls:', ctrl, 'with >=1KB arg:', longs);
console.log('sample:', JSON.stringify(a.slice(0, 4).map((x) => [x[1].slice(0, 50), x[3].slice(0, 50)])));
